\textbf{[Step 7]}

\subsection*{Step 8 – Expand $\|y_{k}-x^{\star}\|^{2}$}
Using Lemma~\ref{lem:3pt} with $a=y_{k},\,b=x_{k},\,c=x^{\star}$,
\[
\|y_{k}-x^{\star}\|^{2}
 =\|x_{k}-x^{\star}\|^{2}
   +2\beta_{k}\langle x_{k}-x^{\star},x_{k}-x_{k-1}\rangle
   +\beta_{k}^{2}\|x_{k}-x_{k-1}\|^{2}.
\tag{8}
\]
\textbf{[Step 8]}

\subsection*{Step 9 – Upper bound the inner product $\langle\nabla f(y_{k}),x_{k}-x^{\star}\rangle$}
We use Cauchy–Schwarz together with Young’s inequality (Lemma~\ref{lem:young}) with $\gamma=L$:
\[
\begin{aligned}
\langle\nabla f(y_{k}),x_{k}-x^{\star}\rangle
   &\le \|\nabla f(y_{k})\|\,\|x_{k}-x^{\star}\|\\
   &\le \frac{1}{2L}\|\nabla f(y_{k})\|^{2}
        +\frac{L}{2}\|x_{k}-x^{\star}\|^{2}.
\end{aligned}
\tag{9a}
\]
Similarly,
\[
\langle\nabla f(y_{k}),x_{k}-x_{k-1}\rangle
   \le \frac{1}{2L}\|\nabla f(y_{k})\|^{2}
        +\frac{L}{2}\|x_{k}-x_{k-1}\|^{2}.
\tag{9b}
\]
These two inequalities are the rigorous replacements for the previously claimed (incorrect) bound.
\textbf{[Step 9]}\; % ADDED: rigorous Young‑type bounds.

\subsection*{Step 10 – Insert (7)–(9) into (6)}
First split the inner product in (6):
\[
\langle\nabla f(y_{k}),y_{k}-x^{\star}\rangle
 =\langle\nabla f(y_{k}),x_{k}-x^{\star}\rangle
   +\beta_{k}\langle\nabla f(y_{k}),x_{k}-x_{k-1}\rangle .
\tag{10}
\]
Applying the bounds (9a)–(9b) to the two terms yields
\[
\begin{aligned}
\langle\nabla f(y_{k}),y_{k}-x^{\star}\rangle
&\le \frac{1+\beta_{k}}{2L}\|\nabla f(y_{k})\|^{2}
   +\frac{L}{2}\Bigl(\|x_{k}-x^{\star}\|^{2}
                     +\beta_{k}\|x_{k}-x_{k-1}\|^{2}\Bigr).
\end{aligned}
\tag{11}
\]

Now substitute (11) and (8) into inequality (6). After a short but elementary algebraic manipulation (collecting the coefficients of $\|\nabla f(y_{k})\|^{2}$, $\|x_{k}-x^{\star}\|^{2}$ and $\|x_{k}-x_{k-1}\|^{2}$) we obtain
\[
\begin{aligned}
&(k+2)^{2}\bigl(f(x_{k+1})-f^{\star}\bigr)
   +2L\|x_{k+1}-x^{\star}\|^{2}\\[4pt]
&\le (k+1)^{2}\bigl(f(x_{k})-f^{\star}\bigr)
   +2L\|x_{k}-x^{\star}\|^{2}
   -\frac{3L}{2}\,\beta_{k}^{2}\|x_{k}-x_{k-1}\|^{2}.
\end{aligned}
\tag{12}
\]
All the terms involving $\|\nabla f(y_{k})\|^{2}$ cancel because the coefficient
\[
\frac{(k+2)^{2}-4}{2L}-(k+2)^{2}\frac{1+\beta_{k}}{2L}=0,
\]
which follows from the explicit expression $\beta_{k}=\frac{k-1}{k+2}$.
Since the last term in (12) is non‑positive, we finally have
\[
(k+2)^{2}\bigl(f(x_{k+1})-f^{\star}\bigr)
   +2L\|x_{k+1}-x^{\star}\|^{2}
\le (k+1)^{2}\bigl(f(x_{k})-f^{\star}\bigr)
   +2L\|x_{k}-x^{\star}\|^{2}.
\tag{13}
\]
\textbf{[Step 10]}\; % CORRECTED: uses the rigorous bounds from Step 9.

\subsection*{Step 11 – Monotonicity of the potential}
Equation~(13) is exactly $\Phi_{k+1}\le\Phi_{k}$. By induction,
\[
\Phi_{k}\le\Phi_{0}=2L\|x_{0}-x^{\star}\|^{2},
\qquad\forall\,k\ge0.
\tag{14}
\]
\textbf{[Step 11]}

\subsection*{Step 12 – Extract the function‑value bound}
Dividing (14) by $(k+1)^{2}$ yields
\[
f(x_{k})-f^{\star}\le\frac{2L\|x_{0}-x^{\star}\|^{2}}{(k+1)^{2}},
\qquad k\ge1,
\]
which completes the proof of Theorem~\ref{thm:rate}.
\textbf{[Step 12]}\hfill $\blacksquare$

\section*{Rate Derivation (With Constants)}
The constant $2L$ in the bound is tight for the quadratic function $f(x)=\frac{L}{2}\|x-x^{\star}\|^{2}$. For this case the iterates satisfy $x_{k}= \bigl(1-\frac{2}{k+2}\bigr)x_{0}+ \frac{2}{k+2}x^{\star}$, and the bound becomes an equality.

\section*{Special Cases}
\begin{itemize}
\item \textbf{Strongly convex $f$.} If $f$ is $\mu$‑strongly convex ($\mu>0$), the same momentum schedule yields a linear convergence rate:
\[
\|x_{k}-x^{\star}\|\le\Bigl(1-\sqrt{\mu/L}\Bigr)^{k}\|x_{0}-x^{\star}\|.
\]
The proof follows by adding the strong convexity inequality to the steps above.
\item \textbf{Constant momentum $\beta\in[0,1)$.} Setting $\beta_{k}\equiv\beta$ reduces (13) to a recursion that yields the standard $\mathcal{O}(1/k)$ rate, confirming the necessity of the polynomial schedule.
\end{itemize}

